// Raw reports whether the packet of an ID has no codec yet and keeps its
// fields as bytes.
func Raw(id uint32) bool {
	switch id {
	case 8, 9, 11, 30, 44, 52, 63, 65, 72, 76, 77, 79, 93, 108, 144, 146, 147, 148, 164, 174, 184, 300, 322, 325, 328, 329, 330, 338, 345:
		return true
	}
	return false
}
